"""The README and LinkedIn visuals, regenerated by one command (S4-0):

    python -m greenleaf_control.media --out docs/media

writes season_replay.gif (README), season_replay.mp4 (LinkedIn: H.264, 1080 px wide),
baselines.png and media.json (each file's source, scenario, commit and numbers).

Every picture is a simulator run on PAPER, graded by metrics on the same run it draws, and its
footer says so: until the ledger has rows, the media shows the simulator and the baselines, never
an RL result. Figures are built without pyplot (headless, no global state), as in viz.
"""

import argparse
import functools
import json
import math
from datetime import UTC, datetime
from pathlib import Path

import numpy as np
import pandas as pd
from matplotlib.animation import FFMpegWriter, FuncAnimation, PillowWriter
from matplotlib.colors import LinearSegmentedColormap
from matplotlib.figure import Figure
from matplotlib.ticker import FuncFormatter, MultipleLocator

from greenleaf_control import envs, evaluate, manifest, metrics, scenarios

N_DAY = 96  # steps a day: 86,400 s / 900 s
CARD = ("rb_default", "zero_controls", "random")  # the card's columns, left to right
U_COLS = [f"u_{name}" for name in evaluate.CONTROLS]  # upstream's control order
ACTUATORS = ("heating", "CO₂", "thermal screen", "vents", "lamps", "blackout screen")
CLIMATE = {"co2": "indoor CO₂ [ppm]", "temp": "temperature [°C]", "rh": "relative humidity [%]"}
HOURS = {"co2": "CO₂", "temp": "temp", "rh": "RH"}  # viz.CLIMATE_LABELS' words
HEADINGS = {
    "rb_default": "upstream's default rule\ncontroller (the grower's rules)",
    "zero_controls": "zero controls\n(everything off, always)",
    "random": "random controls\n(uniform 0 to 1)",
}
PLACE = f"{scenarios.PAPER['location']} {scenarios.PAPER['growth_year']}"  # PAPER's weather
PAPER_NAME = f"PAPER ({PLACE})"
N_FRAMES = 180  # the replay's counter rows; with a 2 s hold at 15 fps, about 14 s
GIF_DPI, MP4_DPI = 100, 150  # 720 x 900 and 1080 x 1350 px on the replay's 7.2 x 9 in figure

# The glasshouse palette.
LEAF, BAND, TOMATO, AMBER = "#2f6b4f", "#d5e7da", "#c23f29", "#a5601c"
INK, MUTED = "#15231c", "#55655c"
ACTUATOR_CMAP = LinearSegmentedColormap.from_list("actuator", ["#f6f1ea", AMBER]).with_extremes(
    bad="white"
)


def play(controller: str, season_length: int = 60) -> dict:
    """One PAPER season of a baseline, graded by metrics: its frame, result, states, controls and
    the model's params."""
    infos = envs.run_baseline(controller, scenarios.PAPER, season_length)
    states, controls = metrics.trace_from_infos(infos)
    env = envs.make_raw_env(
        scenario=scenarios.PAPER, season_length=season_length, normalize_actions=False
    )
    params = np.asarray(env.unwrapped.p, dtype=np.float64)
    env.close()
    result = metrics.episode_metrics(states, controls, params, season_steps=N_DAY * season_length)
    return {
        "frame": evaluate._frame(infos),
        "result": result,
        "states": states,
        "controls": controls,
        "params": params,
    }


def running(states, controls, params, ends) -> pd.DataFrame:
    """The counters: for each k in ends, the metrics of the season's first k steps."""
    cols = ["profit_eur_m2", *(f"viol_hours_{c}" for c in metrics.CONSTRAINTS)]
    rows = []
    for k in ends:
        m = metrics.episode_metrics(states[: k + 1], controls[:k], params, season_steps=k)
        rows.append({"step": k, **{col: m[col] for col in cols}})
    return pd.DataFrame(rows, columns=["step", *cols])


def _days_axis(ax, n_steps: int, n_ticks: int) -> None:
    """x in steps from 0 to n_steps, ticked in days."""
    ax.set_xlim(0, n_steps)
    ax.xaxis.set_major_locator(MultipleLocator(N_DAY * max(1, round(n_steps / N_DAY / n_ticks))))
    ax.xaxis.set_major_formatter(FuncFormatter(lambda x, _: f"{x / N_DAY:g}"))


def _sign(v: float) -> str:
    """Leaf for a profit, tomato for a loss."""
    return LEAF if v >= 0 else TOMATO


def _bad(hours: float) -> str:
    """Tomato for any hours outside a safe range, leaf for none."""
    return TOMATO if hours > 0 else LEAF


def _style(ax) -> None:
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        ax.spines[side].set_color(MUTED)
    ax.tick_params(labelsize=11, colors=MUTED, labelcolor=INK)


def _strip(ax, u: np.ndarray):
    """The 6 x H actuator heat strip (row j = U_COLS[j], column i = hourly row i), on x in steps.
    Nearest-neighbour, so each pixel column is one real hour (smoothing would blur the rows)."""
    image = ax.imshow(
        u,
        cmap=ACTUATOR_CMAP,
        vmin=0.0,
        vmax=1.0,
        aspect="auto",
        interpolation="nearest",
        extent=(0, 4 * u.shape[1], 5.5, -0.5),
    )
    ax.set_yticks(range(6), labels=ACTUATORS)
    ax.tick_params(axis="y", length=0)
    return image


def season_replay(
    frame, counters, out_gif, out_mp4=None, *, title, subtitle=None, footer, fps=15
) -> Figure:
    """Animates a season: each counters row (its first `step` steps) is one frame, then a 2 s hold
    on the last. Hourly co2, temp and rh against t over their safe bands (tomato where outside),
    the actuator strip, and the counters as text, under the title (and the subtitle when given).
    Saves the GIF (and the MP4 when out_mp4 is given) and returns the Figure in its final frame's
    state."""
    hourly = frame.iloc[::4]
    t = hourly["t"].to_numpy()
    u = hourly[U_COLS].to_numpy(dtype=np.float64).T
    n_steps, n_days = len(frame), math.ceil(len(frame) / N_DAY)

    fig = Figure(figsize=(7.2, 9.0), facecolor="white")
    axes = fig.subplots(
        4,
        1,
        sharex=True,
        gridspec_kw={
            "height_ratios": [1, 1, 1, 1.2],
            "left": 0.22,
            "right": 0.96,
            "top": 0.72,
            "bottom": 0.14,
            "hspace": 0.42,
        },
    )
    fig.text(0.04, 0.975, title, fontsize=19, weight="bold", color=INK, va="top")
    if subtitle is not None:
        fig.text(0.04, 0.888, subtitle, fontsize=12.5, color=MUTED, va="top")
    fig.text(0.04, 0.035, footer, fontsize=8, color=MUTED, va="bottom", linespacing=1.4)

    series = {}
    for ax, c in zip(axes[:3], metrics.CONSTRAINTS, strict=True):
        low, high = metrics.BOUNDS[c]
        y = hourly[c].to_numpy(dtype=np.float64)
        ax.axhspan(low, high, color=BAND, lw=0)
        (line,) = ax.plot([], [], color=LEAF, lw=1.1)
        dots = ax.scatter([], [], s=7, color=TOMATO, lw=0, zorder=3)
        lo, hi = min(low, y.min()), max(high, y.max())
        ax.set_ylim(lo - 0.08 * (hi - lo), hi + 0.08 * (hi - lo))
        ax.set_title(CLIMATE[c], loc="left", fontsize=12, color=INK)
        ax.set_title(f"safe {low:g} to {high:g}", loc="right", fontsize=10, color=LEAF)
        _style(ax)
        series[c] = (line, dots, y, (y < low) | (y > high))
    strip = _strip(axes[3], u)
    axes[3].set_title("actuators (pale = off, amber = full)", loc="left", fontsize=12, color=INK)
    _style(axes[3])
    _days_axis(axes[3], n_steps, 6)
    axes[3].set_xlabel("day of the season", fontsize=12, color=INK)

    day = fig.text(0.96, 0.937, "", fontsize=14, color=MUTED, ha="right", va="top")
    fig.text(0.04, 0.83, "profit so far", fontsize=11, color=MUTED, va="top")
    profit = fig.text(0.04, 0.795, "", fontsize=18, weight="bold", va="top")
    fig.text(0.34, 0.83, "hours outside the safe range", fontsize=11, color=MUTED, va="top")
    hours = {
        c: fig.text(x, 0.794, "", fontsize=15, weight="bold", va="top")
        for c, x in zip(metrics.CONSTRAINTS, (0.34, 0.55, 0.80), strict=True)
    }

    def draw(i: int) -> None:
        row = counters.iloc[i]
        k = int(row["step"])
        n = math.ceil(k / 4)  # the hourly rows among the first k steps
        for line, dots, y, out in series.values():
            line.set_data(t[:n], y[:n])
            dots.set_offsets(np.column_stack([t[:n][out[:n]], y[:n][out[:n]]]))
        strip.set_data(np.ma.masked_array(u, mask=np.broadcast_to(np.arange(len(t)) >= n, u.shape)))
        profit.set_text(f"{row['profit_eur_m2']:.2f} €/m²")
        profit.set_color(_sign(row["profit_eur_m2"]))
        day.set_text(f"day {math.ceil(k / N_DAY)} / {n_days}")
        for c, text in hours.items():
            v = row[f"viol_hours_{c}"]
            text.set_text(f"{HOURS[c]} {v:.2f}")
            text.set_color(_bad(v))

    frames = [*range(len(counters)), *[len(counters) - 1] * (2 * fps)]
    anim = FuncAnimation(fig, draw, frames=frames, blit=False, cache_frame_data=False)
    anim.save(out_gif, writer=PillowWriter(fps=fps), dpi=GIF_DPI)
    if out_mp4 is not None:
        writer = FFMpegWriter(fps=fps, codec="h264", extra_args=["-crf", "20"])
        anim.save(out_mp4, writer=writer, dpi=MP4_DPI)
    return fig


def baselines_card(seasons, out, *, footer) -> Figure:
    """rb_default, zero_controls and random side by side: each one's profit, fruit growth and
    hours outside each safe range from its result, then each day's share of steps outside each
    safe range and its actuator strip. Saved to out as a PNG."""
    n_steps = len(seasons[CARD[0]]["frame"])
    fig = Figure(figsize=(10, 7.0), facecolor="white")
    axes = fig.subplots(
        2,
        3,
        sharex=True,
        gridspec_kw={
            "height_ratios": [3, 6],
            "left": 0.14,
            "right": 0.97,
            "top": 0.50,
            "bottom": 0.146,
            "hspace": 0.3,
            "wspace": 0.10,
        },
    )
    fig.text(
        0.03,
        0.975,
        "Profit against climate: three ways to run one greenhouse season",
        fontsize=17,
        weight="bold",
        color=INK,
        va="top",
    )
    fig.text(
        0.03,
        0.922,
        f"One simulated {math.ceil(n_steps / N_DAY)}-day season, {PAPER_NAME}. Profit = fruit value"
        " minus heating, lamp power and CO₂ costs.\nFruit growth is the net change in standing"
        " fruit, not a harvest.",
        fontsize=11,
        color=MUTED,
        va="top",
    )
    fig.text(0.03, 0.015, footer, fontsize=8, color=MUTED, va="bottom", linespacing=1.4)
    outside_cmap = LinearSegmentedColormap.from_list("outside", [BAND, TOMATO])
    for j, c in enumerate(CARD):
        frame, result = seasons[c]["frame"], seasons[c]["result"]
        box = axes[0, j].get_position()
        # say(y, text, **style): a text centred over this column, hanging from y.
        say = functools.partial(fig.text, (box.x0 + box.x1) / 2, ha="center", va="top")
        say(0.85, HEADINGS[c], fontsize=12, weight="bold", color=INK)
        profit = result["profit_eur_m2"]
        say(0.778, f"profit {profit:.2f} €/m²", fontsize=16, weight="bold", color=_sign(profit))
        say(0.735, f"fruit growth {result['yield_kg_m2']:.2f} kg/m²", fontsize=12, color=INK)
        say(0.693, "hours outside the safe range", fontsize=10, color=MUTED)
        for i, k in enumerate(metrics.CONSTRAINTS):
            v = result[f"viol_hours_{k}"]
            say(
                0.665 - 0.034 * i,
                f"{HOURS[k]} {v:.2f} h",
                fontsize=12,
                weight="bold",
                color=_bad(v),
            )
        # Each day's share of its steps outside each safe range: that day's hours / 24.
        outside = np.array(
            [(frame[k] < low) | (frame[k] > high) for k, (low, high) in metrics.BOUNDS.items()],
            dtype=np.float64,
        )
        share = outside.reshape(len(outside), -1, N_DAY).mean(axis=2)
        axes[0, j].imshow(
            share,
            cmap=outside_cmap,
            vmin=0.0,
            vmax=1.0,
            aspect="auto",
            interpolation="nearest",
            extent=(0, N_DAY * share.shape[1], 2.5, -0.5),
        )
        axes[0, j].set_yticks(range(3), labels=[HOURS[k] for k in metrics.BOUNDS])
        _strip(axes[1, j], frame.iloc[::4][U_COLS].to_numpy(dtype=np.float64).T)
        for ax in axes[:, j]:
            _style(ax)
            ax.tick_params(axis="y", length=0, labelleft=j == 0)
        _days_axis(axes[1, j], n_steps, 3)
        axes[1, j].set_xlabel("day", fontsize=12, color=INK)
    axes[0, 0].set_title(
        "share of each day outside the safe range", loc="left", fontsize=11, color=INK
    )
    axes[1, 0].set_title("actuators (pale = off, amber = full)", loc="left", fontsize=11, color=INK)
    fig.savefig(out, dpi=150)
    return fig


def footer(source: str, stamp: dict) -> str:
    """A picture's provenance: its source, the scenario, the simulator's and this repo's commits."""
    gl7 = manifest._versions()["gl-gym"][:7]
    dirty = " (dirty)" if stamp["dirty"] else ""
    return (
        f"source: {source}, {PAPER_NAME}\nsimulator GreenLight-Gym @{gl7}, commit"
        f" {stamp['commit'][:7]}{dirty}. A simulator run, not a registered result"
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="python -m greenleaf_control.media",
        description="Regenerate the README and LinkedIn visuals from the simulator.",
    )
    parser.add_argument("--out", type=Path, required=True, help="the dir to write the media into")
    args = parser.parse_args(argv)
    if not FFMpegWriter.isAvailable():
        parser.error("ffmpeg isn't on PATH, and the MP4 needs it (brew install ffmpeg)")
    stamp = manifest.code_stamp(smoke=True)

    seasons = {c: play(c) for c in CARD}
    invalid = {c: s["result"] for c, s in seasons.items() if not s["result"]["valid"]}
    if invalid:
        parser.error(
            "; ".join(
                f"{c}'s season is invalid ({r['solver_failures']} solver failures, {r['steps']}"
                " steps)"
                for c, r in invalid.items()
            )
            + ": an invalid season is never drawn"
        )
    rb = seasons["rb_default"]
    n_steps = len(rb["frame"])
    ends = [round(n_steps * (i + 1) / N_FRAMES) for i in range(N_FRAMES)]
    counters = running(rb["states"], rb["controls"], rb["params"], ends)
    args.out.mkdir(parents=True, exist_ok=True)
    season_replay(
        rb["frame"],
        counters,
        args.out / "season_replay.gif",
        args.out / "season_replay.mp4",
        title=f"The grower's rules, {n_steps // N_DAY} simulated days\n({PLACE} weather)",
        subtitle="upstream's default rule controller in the GreenLight-Gym simulator",
        footer=footer("rb_default", stamp),
    )
    card_source = " vs ".join(CARD)
    baselines_card(seasons, args.out / "baselines.png", footer=footer(card_source, stamp))

    made_at = datetime.now(UTC).isoformat()
    gl_gym = manifest._versions()["gl-gym"]

    def entry(file: str, source: str, numbers: dict) -> dict:
        return {
            "file": file,
            "source": source,
            "scenario": scenarios.PAPER,
            "commit": stamp["commit"],
            "dirty": stamp["dirty"],
            "gl_gym": gl_gym,
            "made_at": made_at,
            "metrics": numbers,
        }

    entries = [
        entry("season_replay.gif", "rb_default", rb["result"]),
        entry("season_replay.mp4", "rb_default", rb["result"]),
        entry("baselines.png", card_source, {c: seasons[c]["result"] for c in CARD}),
    ]
    (args.out / "media.json").write_text(json.dumps(entries, indent=2) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
